      TParsedOutput
    >,
  ): Router<
    TInputContext,
    TContext,
    TMeta,
    TQueries,
    Record<TPath, inferProcedureFromOptions<TInputContext, typeof procedure>> &
      TMutations,
    TSubscriptions,
    TErrorShape,
